import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Coze learning map","description":"Coze, Coze Programming, and Coze Loop are not one product. This handbook is about building and publishing agents on Coze Programming. Doubao and Trae are out of scope.","frontmatter":{"title":"Coze learning map","description":"Coze, Coze Programming, and Coze Loop are not one product. This handbook is about building and publishing agents on Coze Programming. Doubao and Trae are out of scope.","domain":"product","tags":["agent-builder"],"role":"map"},"headers":[],"relativePath":"products/coze/index.md","filePath":"products/coze/index.md","lastUpdated":1787110548000}'),n={name:"products/coze/index.md"};function s(l,e,d,i,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="coze-learning-map" tabindex="-1">Coze learning map <a class="header-anchor" href="#coze-learning-map" aria-label="Permalink to &quot;Coze learning map&quot;">​</a></h1><blockquote><p><strong>Coze Programming</strong> is the build path in this directory. Official wording (<a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">What is Coze Programming</a>):</p><p>Coze Programming is an AI-driven application platform. Describe the need clearly and it can produce production agents, workflows, skills, mobile apps, web apps, or mini programs.</p><p><strong>Coze</strong> itself is a different door. Official wording (<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">What is Coze</a>): &quot;a next-generation AI team collaboration platform for the Agent era.&quot; You dispatch agents there. You do not draw the low-code canvas there.</p></blockquote><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>ByteDance ships several AI products. Even the ones branded Coze are not the same surface. This directory covers <strong>agent building only</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ByteDance AI (this directory expands the Coze family only)</span></span>
<span class="line"><span>├── Coze (coze.cn) — team workspace for humans + agents</span></span>
<span class="line"><span>│   ├── Coze Agent / cloud Agent / local Agent</span></span>
<span class="line"><span>│   ├── projects, skill store, cloud phone / cloud computer</span></span>
<span class="line"><span>│   └── in-chat AI programming (web / app / mini program; a subset of Coze Programming)</span></span>
<span class="line"><span>├── Coze Programming (code.coze.cn) — build agents / workflows / apps  ← main path</span></span>
<span class="line"><span>│   ├── Low-code: visual agents, workflows, plugins, knowledge</span></span>
<span class="line"><span>│   ├── AI programming: full-code agents / workflows / web / app / mini program / skills</span></span>
<span class="line"><span>│   └── Coze CLI (npm @coze/cli)</span></span>
<span class="line"><span>├── Coze Loop (commercial name: 扣子罗盘) — prompts / eval / traces</span></span>
<span class="line"><span>├── Open-source cores</span></span>
<span class="line"><span>│   ├── Coze Studio (self-host the builder)</span></span>
<span class="line"><span>│   └── Coze Loop OSS</span></span>
<span class="line"><span>└── Same vendor, not documented here</span></span>
<span class="line"><span>    ├── Doubao — chat (#79)</span></span>
<span class="line"><span>    ├── Trae — coding IDE (#80)</span></span>
<span class="line"><span>    └── Volcengine Ark — model API (#82)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Product</th><th>What it is</th><th>Entry</th><th>This site</th></tr></thead><tbody><tr><td><strong>Coze Programming</strong></td><td>Build, debug, and publish agents in the browser</td><td><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a></td><td><a href="./coze.html">Tutorial</a></td></tr><tr><td>Coze</td><td>Consumer AI team workspace (web / desktop / app)</td><td><a href="https://www.coze.cn/" target="_blank" rel="noreferrer">coze.cn</a></td><td>One map row; <a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">official start</a></td></tr><tr><td>Coze Loop</td><td>Prompt, evaluation, traces</td><td><a href="https://docs.coze.cn/cozeloop_what-is-cozeloop" target="_blank" rel="noreferrer">What is Coze Loop</a></td><td>One map row</td></tr><tr><td>Coze Studio</td><td>Open-source single-node engine</td><td><a href="https://github.com/coze-dev/coze-studio" target="_blank" rel="noreferrer">github.com/coze-dev/coze-studio</a></td><td>One map row; commercial cloud is not self-hosted</td></tr><tr><td>Coze Loop OSS</td><td>Open core of Loop</td><td><a href="https://github.com/coze-dev/coze-loop" target="_blank" rel="noreferrer">github.com/coze-dev/coze-loop</a></td><td>One map row</td></tr><tr><td>Coze.com</td><td>International site</td><td><a href="https://www.coze.com/" target="_blank" rel="noreferrer">coze.com</a>, <a href="https://docs.coze.com/" target="_blank" rel="noreferrer">docs.coze.com</a></td><td>One map row; accounts and channels differ</td></tr><tr><td>Coze Pro / Enterprise</td><td>Enterprise plan on Volcengine</td><td><a href="https://www.volcengine.com/product/coze-pro" target="_blank" rel="noreferrer">volcengine.com/product/coze-pro</a></td><td>One map row; <a href="https://docs.coze.cn/guides_edition" target="_blank" rel="noreferrer">plans</a></td></tr><tr><td>Doubao</td><td>Same-vendor chat</td><td><a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a></td><td><strong>No tutorial</strong> → #79</td></tr><tr><td>Trae</td><td>Same-vendor IDE</td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">trae.cn</a>, <a href="https://www.trae.ai/" target="_blank" rel="noreferrer">trae.ai</a></td><td><strong>No tutorial</strong> → #80</td></tr><tr><td>Ark</td><td>Same-vendor model API</td><td><a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">volcengine.com/product/ark</a></td><td><strong>No tutorial</strong> → #82</td></tr><tr><td>Feishu / WeChat / Douyin</td><td>Publish channels, not Coze products</td><td><a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">Publish overview</a></td><td>Not this site</td></tr></tbody></table><p><strong>Names that collide</strong></p><ul><li><strong>Coze ≠ Coze Programming.</strong> Workspace vs builder.</li><li><strong>Coze ≠ Doubao.</strong> Doubao is chat. The low-code “publish to Doubao” channel closed on <strong>2026-07-01</strong> (<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>).</li><li><strong>Coze Programming ≠ Trae.</strong> Trae is an IDE.</li><li><strong>Low-code agent ≠ full-code agent.</strong> Visual canvas vs AI-programming chat.</li><li><strong>Cloud “Claude Code / Codex CLI” ≠ vendor CLIs.</strong> Those frameworks run on a Coze cloud computer. You cannot sign in to Anthropic or OpenAI there (<a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">consumer FAQ</a>).</li><li><strong>Coze Studio ≠ Coze Programming.</strong> Studio is the open single-node core. Commercial Coze Programming does not offer private deployment.</li><li>Older <strong>Bot</strong> = today’s low-code agent.</li></ul><h3 id="decision-tree" tabindex="-1">Decision tree <a class="header-anchor" href="#decision-tree" aria-label="Permalink to &quot;Decision tree&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do you need?</span></span>
<span class="line"><span>├── Zero-code conversational agent, then Feishu / WeChat / API</span></span>
<span class="line"><span>│   └── Coze Programming · low-code agent (start with the tutorial)</span></span>
<span class="line"><span>├── Fixed pipeline (report, batch, multi-step tools)</span></span>
<span class="line"><span>│   └── Coze Programming · low-code workflow (Cookbook)</span></span>
<span class="line"><span>├── One sentence → full-code agent / web / app / mini program</span></span>
<span class="line"><span>│   └── Coze Programming · AI programming (Cookbook)</span></span>
<span class="line"><span>├── Drive Coze from a terminal or another agent</span></span>
<span class="line"><span>│   └── Coze CLI</span></span>
<span class="line"><span>├── Work with several agents, PPT / video, local files</span></span>
<span class="line"><span>│   └── Coze (coze.cn) — not a step-by-step tutorial here</span></span>
<span class="line"><span>├── Prompt eval and traces</span></span>
<span class="line"><span>│   └── Coze Loop</span></span>
<span class="line"><span>├── Data must stay on your machines</span></span>
<span class="line"><span>│   └── Coze Studio (Programming itself cannot be self-hosted)</span></span>
<span class="line"><span>├── Chat / copywriting only</span></span>
<span class="line"><span>│   └── Doubao (#79)</span></span>
<span class="line"><span>└── Repo IDE</span></span>
<span class="line"><span>    └── Trae (#80), or Claude Code / Cursor / Grok Build on this site</span></span></code></pre></div><p>Sources: <a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">what_is_coze</a>, <a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">guides_welcome</a>, <a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>, <a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">guides_FAQ</a>, <a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">cozespace_coze_app_faq</a>.</p><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Goals</strong></p><ul><li>Pick the right Coze door.</li><li>Follow the official path to a published low-code agent.</li><li>Jump to a recipe when you need workflows, knowledge, plugins, skills, or the CLI.</li></ul><p><strong>Non-goals</strong></p><ul><li>No full Doubao, Trae, or Ark tutorials.</li><li>No PPT / short-video / cloud-phone office manual.</li><li>No model internals (see <a href="/tech/fundamentals/LLM.html">Learn LLM</a>).</li><li>No private-cloud implementation guide for Studio.</li></ul><h2 id="which-page" tabindex="-1">Which page <a class="header-anchor" href="#which-page" aria-label="Permalink to &quot;Which page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Type</th><th>When</th></tr></thead><tbody><tr><td><a href="./coze.html">Tutorial</a></td><td>Tutorial</td><td>First time: sign up → low-code agent → debug → publish</td></tr><tr><td><a href="./coze-cookbook.html">Cookbook</a></td><td>How-to</td><td>You can click the UI; you have one job</td></tr><tr><td><a href="./coze-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>Plans, channels, CLI, limits, sources</td></tr><tr><td><a href="./coze-glossary.html">Glossary</a></td><td>Explanation</td><td>Colliding names, or an old Bot tutorial</td></tr></tbody></table><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Outcome</th></tr></thead><tbody><tr><td>1. Pick a door</td><td>This map</td><td>Do not open Doubao or Trae by mistake</td></tr><tr><td>2. Ship one agent</td><td><a href="./coze.html">Tutorial</a></td><td>Official “praise bot” path</td></tr><tr><td>3. Add capability</td><td><a href="./coze-cookbook.html">Cookbook</a></td><td>Plugin / knowledge / workflow / publish / CLI</td></tr><tr><td>4. Look up</td><td><a href="./coze-cheatsheet.html">Cheatsheet</a></td><td>Plans and commands</td></tr><tr><td>5. Align words</td><td><a href="./coze-glossary.html">Glossary</a></td><td>Skill vs plugin vs workflow</td></tr></tbody></table><h2 id="feature-index-builder-surface" tabindex="-1">Feature index (builder surface) <a class="header-anchor" href="#feature-index-builder-surface" aria-label="Permalink to &quot;Feature index (builder surface)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>One line</th><th>Official</th></tr></thead><tbody><tr><td>Low-code agent</td><td>Persona + model + skills panel</td><td><a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">Overview</a>, <a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">Quick start</a></td></tr><tr><td>Full-code agent</td><td>Chat produces a deployable project</td><td><a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">Develop an agent</a></td></tr><tr><td>Workflow / chatflow</td><td>Drag nodes; chatflow is for chatbots</td><td><a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">Low-code workflow</a></td></tr><tr><td>Plugin</td><td>One plugin, many API tools</td><td><a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td>Knowledge</td><td>Documents / tables / images; plus Volcengine knowledge</td><td><a href="https://docs.coze.cn/guides_knowledge" target="_blank" rel="noreferrer">Knowledge</a></td></tr><tr><td>Memory</td><td>Variables, database, long-term memory</td><td><a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">Overview · memory</a></td></tr><tr><td>Skill</td><td><code>SKILL.md</code> folder, loaded on demand</td><td><a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">Skills</a></td></tr><tr><td>Publish</td><td>Store, Feishu, WeChat, mini programs, API, Chat SDK</td><td><a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">Publish</a></td></tr><tr><td>Coze CLI</td><td><code>npm i -g @coze/cli</code>, binary <code>coze</code></td><td><a href="https://docs.coze.cn/developer_guides_coze_cli" target="_blank" rel="noreferrer">Coze CLI</a></td></tr></tbody></table><h2 id="freshness" tabindex="-1">Freshness <a class="header-anchor" href="#freshness" aria-label="Permalink to &quot;Freshness&quot;">​</a></h2><ul><li><strong>Coze 3.0</strong>: official date <strong>2026-05-29</strong> for multi-agent collaboration (<a href="https://docs.coze.cn/cozespace_coze_app_faq" target="_blank" rel="noreferrer">consumer FAQ</a>).</li><li><strong>Doubao publish channel</strong> for low-code agents: closed <strong>2026-07-01</strong>.</li><li><strong>Douyin avatar</strong>: removed 2025-09-03.</li><li><strong>Workflow / image-flow store</strong>: taken down.</li><li>Ignore 2024 blogs that still say “Bot + one-click Discord / Doubao”.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./coze.html">Tutorial</a></li><li><a href="./coze-cookbook.html">Cookbook</a></li><li><a href="./coze-cheatsheet.html">Cheatsheet</a></li><li><a href="./coze-glossary.html">Glossary</a></li><li><a href="./../">Products</a></li></ul>`,26)])])}const b=t(n,[["render",s]]);export{f as __pageData,b as default};
